"""Approved complementary practice; independent of the eight-task ESL Pals sequence."""
GROUPS = [
    ('Meeting someone', 'Questions and short answers with be'),
    ('Everyday life', 'Questions and short answers with do and does'),
    ('Likes and preferences', 'Enjoy, negative preferences and third-person forms'),
    ('Personality and shared interests', 'Describe, explain and connect ideas'),
    ('Keep the conversation going', 'Follow-up questions and a final exchange'),
]

QUESTIONS = [
    dict(id='q1', group=1, context='Laura wants to ask Mateo about his hometown.', question='Complete Laura’s question: “Where ___ you from?”', options={'A':'do','B':'are','C':'is'}, answer='B', model='Where are you from?', explanation='Use be with from to ask about origin. With you, use are. Do is used with another main verb, as in Where do you live?'),
    dict(id='q2', group=1, context='Laura says she is creative. Mateo wants to confirm this with another classmate.', question='Complete the question: “___ Laura creative?”', options={'A':'Does','B':'Are','C':'Is'}, answer='C', model='Is Laura creative?', explanation='Creative is an adjective. Use Is + Laura + adjective. Does needs a main verb, and are does not agree with Laura.'),
    dict(id='q3', group=1, context='Laura says, “I am organized. I prepare my bag every evening.” Mateo asks, “Are you organized?”', question='Choose Laura’s correct short answer.', options={'A':'Yes, I am.','B':'Yes, I do.','C':'Yes, I’m.'}, answer='A', model='Are you organized? Yes, I am.', explanation='A question with are takes a short answer with am when the speaker is I. Do does not match be. Do not end an affirmative short answer with the contraction I’m.'),
    dict(id='q4', group=2, context='Mateo wants to know where Laura lives.', question='Complete the question: “Where ___ you live?”', options={'A':'are','B':'is','C':'do'}, answer='C', model='Where do you live?', explanation='Live is the main verb. In a present-simple question with you, put do before the subject and keep live in its base form.'),
    dict(id='q5', group=2, context='Laura works in a bakery. Mateo works in a small shop. Another learner asks about Mateo’s job.', question='Complete the question: “___ Mateo work in a small shop?”', options={'A':'Do','B':'Does','C':'Is'}, answer='B', model='Does Mateo work in a small shop?', explanation='Mateo is one person, like he, so use does. After does, the main verb stays in the base form: work, not works.'),
    dict(id='q6', group=2, context='Laura says, “I enjoy cooking.” A classmate asks Mateo, “Does Laura enjoy cooking?”', question='Choose Mateo’s correct short answer.', options={'A':'Yes, she does.','B':'Yes, she is.','C':'Yes, she do.'}, answer='A', model='Does Laura enjoy cooking? Yes, she does.', explanation='The question uses does, so repeat does in the short answer. She is used with does, not do. Is does not match the auxiliary in this question.'),
    dict(id='q7', group=3, context='Laura talks about relaxing on weekdays.', question='Complete the sentence: “I enjoy ___ after work.”', options={'A':'to listen to music','B':'listening to music','C':'listen to music'}, answer='B', model='I enjoy listening to music after work.', explanation='After enjoy, use a noun or an -ing form. Here, listening to music is the activity. Enjoy to listen and enjoy listen are not correct.'),
    dict(id='q8', group=3, context='Mateo says, “Noisy places are not enjoyable for me.” Laura reports his preference.', question='Which sentence expresses Mateo’s dislike correctly?', options={'A':'He isn’t like noisy places.','B':'He doesn’t likes noisy places.','C':'He doesn’t like noisy places.'}, answer='C', model='He doesn’t like noisy places.', explanation='For a negative preference with he, use doesn’t + like. The auxiliary already marks the third person, so like has no final s. Isn’t does not form this negative with like.'),
    dict(id='q9', group=3, context='Mateo likes both reading and listening to music, but reading is his first choice after work.', question='Complete Laura’s report: “Mateo ___ reading after work.”', options={'A':'prefer','B':'is prefer','C':'prefers'}, answer='C', model='Mateo prefers reading after work.', explanation='This is a statement about Mateo, so use the third-person form prefers. Prefer shows his choice between two activities. Do not add is before this present-simple verb.'),
    dict(id='q10', group=4, context='Mateo describes himself: “I’m quiet in large groups. I don’t talk much in that situation.”', question='Which sentence describes the personality Mateo reports?', options={'A':'He is quiet in large groups.','B':'He likes quiet places.','C':'He quiet in large groups.'}, answer='A', model='He is quiet in large groups.', explanation='Use be + adjective for the description: He is quiet. He likes quiet places expresses a preference that Mateo did not state. He quiet is missing the verb.'),
    dict(id='q11', group=4, context='Laura says, “I’m organized. I prepare my bag every evening.”', question='Which sentence connects her description with the example she gives?', options={'A':'She is organized because she prepares no plans or materials.','B':'She is organized because she prepares her bag every evening.','C':'She is organized, but she prepares her bag every evening.'}, answer='B', model='She is organized because she prepares her bag every evening.', explanation='Because introduces the reason or supporting example. Preparing her bag supports organized. But would suggest a contrast, and the first option changes Laura’s information.'),
    dict(id='q12', group=4, context='Laura enjoys cooking. Mateo enjoys cooking too. They identify this shared interest.', question='Choose the sentence they can say together.', options={'A':'We both like cooking.','B':'We both likes cooking.','C':'We are both like cooking.'}, answer='A', model='We both like cooking.', explanation='Both refers to the two people and goes before like here. With we, use like without s. Do not add are before the main verb like.'),
    dict(id='q13', group=5, context='Mateo says, “I enjoy cooking. I often make soup.” Laura wants one more detail about the soup.', question='Which follow-up question best fits her purpose?', options={'A':'Where are you from?','B':'What do you usually read?','C':'What kind of soup do you usually make?'}, answer='C', model='What kind of soup do you usually make?', explanation='A follow-up question builds on the answer. This question asks for the extra detail about soup that Laura wants. The other questions change the topic.'),
    dict(id='q14', group=5, context='Laura says, “I prefer listening to music on weekdays.” Mateo wants to learn about her musical tastes.', question='Which follow-up question continues that topic?', options={'A':'What kind of music do you like?','B':'What do you do for work?','C':'How do you spell your last name?'}, answer='A', model='What kind of music do you like?', explanation='Laura has mentioned music. Asking about the kind of music develops that topic. The other questions are possible in an introduction, but do not ask about her musical tastes.'),
    dict(id='q15', group=5, context='Mateo: “I’m quiet and patient.” Laura: “I enjoy cooking and walking.” Choose questions that match the purpose and the answer in each turn.', question='First ask about Mateo’s personality; then ask about Laura’s favorite activities.', options={'A':'What do you like doing? / What are you like?','B':'What are you like? / What do you like doing?','C':'What do you like? / What do you like?'}, answer='B', model='What are you like? I’m quiet and patient. What do you like doing? I enjoy cooking and walking.', explanation='What are you like? asks about personality. What do you like doing? asks about activities and preferences. The order matters because each question must match its answer.'),
]

